const GHZ_STAFF_PAGE_KEY='ghz-staff-page';
const GHZ_STAFF_PAGES=new Set(['home','shipments','tracking','dispatch','drivers','clients','pricing','campaigns','analytics','staff','proof']);
function readStaffPage(){
  try{
    const value=sessionStorage.getItem(GHZ_STAFF_PAGE_KEY)||'';
    return GHZ_STAFF_PAGES.has(value)?value:'';
  }catch(_){return ''}
}
function rememberStaffPage(id){
  try{
    if(GHZ_STAFF_PAGES.has(id))sessionStorage.setItem(GHZ_STAFF_PAGE_KEY,id);
    else if(!id)sessionStorage.removeItem(GHZ_STAFF_PAGE_KEY);
  }catch(_){}
}
