function customerUiText(group,key){const row=group?.[key];return row?(row[customerLang]||row.en||Object.values(row)[0]||''):''}
function customerSetButtonLabel(button,label){
  if(!button||!label)return;
  const nodes=[...button.childNodes].filter(node=>node.nodeType===Node.TEXT_NODE&&String(node.nodeValue||'').trim());
  if(nodes.length){nodes[nodes.length-1].nodeValue=' '+label;return}
  const labelNode=button.querySelector('[data-label],.label,.nav-label,span:last-child,small');
  if(labelNode){labelNode.textContent=label;return}
  button.append(document.createTextNode(' '+label));
}
function customerApplyBottomNavLabels(){
  if(!customerMobileNav)return;
  customerMobileNav.querySelectorAll('[data-customer-page]').forEach(button=>{
    const label=customerUiText(CUSTOMER_NAV_UI,String(button.dataset.customerPage||'').trim());
    if(label)customerSetButtonLabel(button,label);
  });
}
function customerApplyLanguageNames(){
  const select=document.querySelector('#customerLanguageSelect');
  if(!select)return;
  const nativeNames={en:'English',ur:'اردو',ar:'العربية',hi:'हिन्दी',bn:'বাংলা'};
  [...select.options].forEach(option=>{
    const code=String(option.value||'').trim();
    if(nativeNames[code])option.textContent=nativeNames[code];
  });
  select.value=customerLang;
}

function customerTranslate(value){
  const text=String(value??'');
  const direct=CUSTOMER_TRANSLATIONS[text];
  const source=direct?text:CUSTOMER_TRANSLATION_ALIASES[text];
  const row=source?CUSTOMER_TRANSLATIONS[source]:null;
  if(row){
    if(customerLang==='ar') return row.ar||source;
    return row[customerLang]||row.en||source;
  }
  if(customerLang!=='bn'&&window.LOCALES?.[customerLang]){
    try{return window.GhazalaI18n.translate(text,customerLang)}catch(_){}
  }
  return text;
}

function customerLocalize(root){
  if(!root)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[];
  while(walker.nextNode())nodes.push(walker.currentNode);
  nodes.forEach(node=>{
    const raw=node.nodeValue||'';
    const trimmed=raw.trim();
    if(!trimmed)return;
    const translated=customerTranslate(trimmed);
    if(translated!==trimmed)node.nodeValue=raw.replace(trimmed,translated);
  });
  root.querySelectorAll?.('[placeholder],[title],[aria-label]').forEach(el=>{
    ['placeholder','title','aria-label'].forEach(attr=>{
      if(!el.hasAttribute(attr))return;
      const current=el.getAttribute(attr);
      const translated=customerTranslate(current);
      if(translated!==current)el.setAttribute(attr,translated);
    });
  });
}

function customerApplyLanguage(){
  const rtl=['ar','ur'].includes(customerLang);
  const dir=rtl?'rtl':'ltr';
  if(customerPortalRoot){
    customerPortalRoot.lang=customerLang;
    customerPortalRoot.dir=dir;
  }
  if(customerMobileNav){
    customerMobileNav.lang=customerLang;
    customerMobileNav.dir=dir;
  }
  const bar=document.querySelector('#customerLanguageBar');
  const select=document.querySelector('#customerLanguageSelect');
  if(bar){
    bar.lang=customerLang;
    bar.dir='ltr';
  }
  if(select)select.value=customerLang;

  document.documentElement.lang=customerLang;
  document.documentElement.dir=dir;

  customerLocalize(customerPortalRoot);
  customerLocalize(customerMobileNav);
  customerLocalize(document.querySelector('#modalRoot'));
  customerApplyBottomNavLabels();
  customerApplyLanguageNames();

  const accountLanguage=document.querySelector('.customer-account-row[data-customer-action="language"] small');
  if(accountLanguage)accountLanguage.textContent=CUSTOMER_LANGUAGES[customerLang]||customerLang;

  const quote=document.querySelector('#customerQuoteTotal');
  if(quote?.dataset.amount){
    quote.textContent=Number(quote.dataset.amount).toFixed(2)+' '+customerTranslate('ر.س');
  }
}

function setCustomerLanguage(code){
  if(!Object.prototype.hasOwnProperty.call(CUSTOMER_LANGUAGES,code))return;

  // One language state for the live customer portal. Previously customerLang could
  // become English while currentLang stayed Arabic, so the global i18n layer could
  // translate freshly-rendered English labels back into Arabic.
  customerLang=code;
  currentLang=code;
  localStorage.setItem('ghz-customer-language',customerLang);
  localStorage.setItem('ghz-language',currentLang);
  try{window.GhazalaI18n.setLanguage(currentLang)}catch(_){}

  if(customerMode&&customerPortalRoot&&!customerPortalRoot.hidden){
    const modalRoot=document.querySelector('#modalRoot');
    if(modalRoot&&modalRoot.children.length)modalRoot.replaceChildren();
    renderCustomerPortal();
  }else{
    applyLanguage();
    customerApplyLanguage();
  }

  customerApplyLanguageNames();
}

