const currencyLabel=()=>phrase('ر.س');
const money=n=>Number(n||0).toLocaleString(currentLang==='ar'?'ar-SA':currentLang==='ur'?'ur-PK':currentLang==='hi'?'hi-IN':'en-GB')+' '+currencyLabel();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function translateText(text){return window.GhazalaI18n.translate(text,currentLang)}
function phrase(text){return translateText(text)}
const accessRoleLabels={system_admin:'مدير النظام',branch_manager:'مدير الفرع',office_employee:'موظف المكتب',courier:'مندوب التوصيل',accountant:'المحاسب',customer:'العميل (محجوز)'};
function accessRole(account=user){return account?.access_role||({admin:'system_admin',manager:'branch_manager',employee:'courier'})[account?.role]||'customer'}
function hasPermission(permission){if(!user)return false;if(Array.isArray(user.permissions))return user.permissions.includes(permission);if(user.role==='admin')return true;if(user.role==='manager')return !['users.manage','audit.read','demo.reset'].includes(permission);return user.role==='employee'&&['shipments.read','shipments.status','pod.read','pod.create','drivers.read','drivers.location','routes.read','branches.read','vehicles.read','pricing.read','stats.read'].includes(permission)}
function requirePermission(permission){if(hasPermission(permission))return true;toast(phrase('ليست لديك صلاحية لهذا الإجراء'));return false}
function canPage(id){if(id==='landing')return true;if(id==='business')return !user||accessRole()!=='customer';if(!user||accessRole()==='customer')return false;if(id==='home')return hasPermission('stats.read')||hasPermission('shipments.read');const permissions={shipments:'shipments.read',tracking:'shipments.read',dispatch:'routes.read',drivers:'drivers.read',clients:'clients.read',pricing:'pricing.read',campaigns:'campaigns.read',analytics:'reports.read',staff:'users.manage',proof:'pod.read'};return !!permissions[id]&&hasPermission(permissions[id])}
function canAction(type){if(type==='branch'&&accessRole()!=='system_admin')return false;const permissions={create:'shipments.create',route:'routes.manage',vehicle:'vehicles.manage',branch:'branches.manage',client:'clients.manage',campaign:'campaigns.manage',driver:'drivers.manage',staff:'users.manage','reset-demo':'demo.reset',export:'reports.read','export-pdf':'reports.read','export-xlsx':'reports.read',quote:'pricing.read',contract:'clients.read'};return !permissions[type]||hasPermission(permissions[type])}
function applyPermissionControls(root=document){root.querySelectorAll('[data-page]').forEach(button=>{if(!canPage(button.dataset.page))button.remove()});root.querySelectorAll('[data-action]').forEach(button=>{if(!canAction(button.dataset.action))button.remove()});const controls={'data-status':'shipments.status','data-reassign':'shipments.assign','data-location':'drivers.location','data-assign-driver':'drivers.manage','data-route-scan':'routes.manage','data-route-status':'routes.manage','data-route-manifest':'routes.read','data-payment-awb':'shipments.payment','data-driver-location':'drivers.location','data-client-view':'clients.read','data-client-edit':'clients.manage','data-client-toggle':'clients.manage','data-campaign-manage':'campaigns.manage','data-campaign-type':'campaigns.manage','data-user-edit':'users.manage','data-user-toggle':'users.manage','data-user-revoke':'users.manage'};for(const [attribute,permission] of Object.entries(controls))if(!hasPermission(permission))root.querySelectorAll('['+attribute+']').forEach(button=>button.remove())}
function sessionContext(){const primary=user?.branches?.find(branch=>String(branch.id)===String(user.primary_branch_id));const branch=primary||user?.branches?.[0];return [user?.display_name,phrase(accessRoleLabels[accessRole()]||'موظف'),branch?`${branch.name} · ${ghazalaCityDisplay(branch.city,currentLang)}`:phrase(accessRole()==='system_admin'?'جميع الفروع':'بدون فرع')].filter(Boolean).join(' · ')}
function branchWorkspaceBanner(){
  if(!user||accessRole()==='customer')return '';
  const primary=user?.branches?.find(branch=>String(branch.id)===String(user.primary_branch_id))||user?.branches?.[0];
  if(accessRole()==='system_admin'){
    return `<div class="branch-workspace-banner global"><span>⌂</span><div><b>${currentLang==='ar'?'مساحة إدارة جميع الفروع':'All Branches Workspace'}</b><small>${currentLang==='ar'?'جدة + جازان':'Jeddah + Jazan'}</small></div></div>`;
  }
  if(!primary)return '';
  return `<div class="branch-workspace-banner"><span>⌂</span><div><b>${esc(primary.name)}</b><small>${esc(ghazalaCityDisplay(primary.city,currentLang))} · ${esc(primary.code||'')}</small></div></div>`;
}
function applyLanguage(){window.GhazalaI18n.setLanguage(currentLang);document.querySelector('#langSelect').value=currentLang;document.querySelector('#logoutBtn').hidden=!user;document.querySelector('#passwordBtn').hidden=!user;document.title=phrase('غزالا ترانسبورت | الشحن والخدمات اللوجستية في السعودية');localize(document.head)}
function localize(root){window.GhazalaI18n.localize(root)}
function changeLanguage(next){currentLang=window.LOCALES[next]?next:'ar';localStorage.setItem('ghz-language',currentLang);applyLanguage();localize(document.body);window.dispatchEvent(new CustomEvent('ghazala:languagechange',{detail:{language:currentLang}}))}
async function api(url,opts={}){
  const r=await fetch(url,{
    credentials:'same-origin',
    headers:{'Content-Type':'application/json',...(opts.headers||{})},
    ...opts
  });
  let d={};
  try{d=await r.json()}catch(_){d={error:`HTTP ${r.status}`}}
  if(!r.ok){
    const error=Error(d.error||'تعذر إكمال الطلب');
    error.status=r.status;
    throw error;
  }
  return d;
}


