function canUpdateAtCurrentBranch(s){
  if(!user||accessRole()==='customer'||!hasPermission('shipments.status'))return false;
  if(accessRole()==='system_admin'&&user.global_scope===true)return true;
  const branches=Array.isArray(user.branches)?user.branches:[];
  return branches.some(branch=>String(branch.city||'').trim()===String(s.origin||'').trim());
}
function canReceiveAtCurrentBranch(s){
  if(!user||accessRole()==='customer'||!hasPermission('shipments.status'))return false;
  return s.can_receive_at_branch===true;
}
async function receiveShipmentAtBranch(awb){
  const s=shipments.find(item=>item.awb===awb);
  if(!s)return;
  const label=currentLang==='ar'?'تأكيد استلام الشحنة في الفرع؟':'Confirm receipt of this shipment at the destination branch?';
  if(!window.confirm(label))return;
  try{
    await api('/api/shipments/'+encodeURIComponent(awb)+'/receive-branch',{method:'POST',body:'{}'});
    toast(currentLang==='ar'?'تم استلام الشحنة في الفرع':'Shipment received at destination branch');
    await load();
  }catch(error){toast(error.message)}
}

