function bindLandingInteractions() {
  // Bind all smooth scroll buttons and links
  document.querySelectorAll('a[href^="#"], [data-scroll]').forEach(btn => {
    btn.onclick = (e) => {
      const targetId = btn.dataset.scroll || btn.getAttribute('href')?.replace('#', '');
      if (!targetId || targetId === 'top') {
        if (targetId === 'top') {
          e.preventDefault();
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }
        return;
      }
      const el = document.getElementById(targetId);
      if (el) {
        e.preventDefault();
        // Remove active state from all nav links
        document.querySelectorAll('.landing-links a, .topbar-guest-nav a').forEach(a => a.classList.remove('active'));
        btn.classList.add('active');

        const headerOffset = 85;
        const targetPos = el.getBoundingClientRect().top + window.pageYOffset - headerOffset;
        window.scrollTo({ top: Math.max(0, targetPos), behavior: 'smooth' });

        // Trigger 3D section highlight
        el.classList.add('section-highlight-3d');
        setTimeout(() => el.classList.remove('section-highlight-3d'), 2000);
      }
    };
  });

  // 3D Card tilt effect on mouse movement for services
  document.querySelectorAll('.service-card-3d').forEach(card => {
    card.onmousemove = (e) => {
      const rect = card.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const centerX = rect.width / 2;
      const centerY = rect.height / 2;
      const rotateX = ((y - centerY) / centerY) * -6;
      const rotateY = ((x - centerX) / centerX) * 6;
      card.style.transform = `perspective(1000px) rotateX(${rotateX.toFixed(2)}deg) rotateY(${rotateY.toFixed(2)}deg) translateY(-8px) translateZ(14px)`;
      card.style.borderColor = 'rgba(217, 131, 36, 0.55)';
    };
    card.onmouseleave = () => {
      card.style.transform = '';
      card.style.borderColor = '';
    };
  });

  // Service filter tabs
  document.querySelectorAll('.service-tab-btn').forEach(tab => {
    tab.onclick = () => {
      document.querySelectorAll('.service-tab-btn').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      const cat = tab.dataset.serviceCategory;
      document.querySelectorAll('.service-card-3d').forEach(card => {
        if (cat === 'all' || card.dataset.category === cat) {
          card.style.display = '';
        } else {
          card.style.display = 'none';
        }
      });
    };
  });

  // Interactive Route station pins
  document.querySelectorAll('.station-pill').forEach(pill => {
    pill.onclick = () => {
      document.querySelectorAll('.station-pill').forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
      const st = pill.dataset.station;
      document.querySelectorAll('.station-info-panel').forEach(panel => {
        panel.classList.toggle('active', panel.dataset.station === st);
      });
    };
  });

  // Step cards 3D hover
  document.querySelectorAll('.step-card-3d').forEach(step => {
    step.onmouseenter = () => {
      document.querySelectorAll('.step-card-3d').forEach(s => s.classList.remove('spotlight'));
      step.classList.add('spotlight');
    };
  });
}

