function customerCampaignText(key){
  const row=CUSTOMER_CAMPAIGN_TEXT[key]||{};
  return row[customerLang]||row.en||key;
}
function customerCampaignDate(value){
  if(!value)return '';
  const d=new Date(String(value).replace(' ','T')+'Z');
  if(Number.isNaN(d.getTime()))return String(value);
  try{return d.toLocaleString(customerLang==='ar'?'ar-SA':customerLang==='ur'?'ur-PK':'en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}
  catch(_){return String(value)}
}
function customerOfferCard(offer){
  const discount=Number(offer.discount_percent||0);
  const code=String(offer.coupon_code||'').trim();
  const minimum=Number(offer.min_order_amount||0);
  const maximum=offer.max_discount_amount===null||offer.max_discount_amount===undefined||offer.max_discount_amount===''?null:Number(offer.max_discount_amount);
  return `<article style="border:1px solid #f0d8c7;border-radius:18px;padding:15px;background:linear-gradient(135deg,#fffaf6,#fff);box-shadow:0 8px 24px rgba(76,48,28,.06)">
    <div style="display:flex;gap:12px;align-items:flex-start">
      <div style="min-width:48px;height:48px;border-radius:14px;display:grid;place-items:center;background:#fff0e5;color:#ff651f;font-weight:900;font-size:17px">${discount?`${discount}%`:'%'}</div>
      <div style="flex:1;min-width:0">
        <strong style="display:block;font-size:16px;color:#12263e">${esc(offer.name||'Offer')}</strong>
        ${offer.message?`<p style="margin:5px 0 0;color:#596b80;font-size:12px;line-height:1.55">${esc(offer.message)}</p>`:''}
      </div>
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:7px;margin-top:12px;font-size:11px;color:#53677d">
      ${code?`<span style="padding:5px 9px;border-radius:999px;background:#f4f7fa">${customerCampaignText('code')}: <b>${esc(code)}</b></span>`:''}
      ${minimum>0?`<span style="padding:5px 9px;border-radius:999px;background:#f4f7fa">${customerCampaignText('minOrder')}: <b>${minimum.toLocaleString()} ${customerCampaignText('sar')}</b></span>`:''}
      ${maximum!==null&&maximum>0?`<span style="padding:5px 9px;border-radius:999px;background:#f4f7fa">${customerCampaignText('maxDiscount')}: <b>${maximum.toLocaleString()} ${customerCampaignText('sar')}</b></span>`:''}
      ${offer.remaining_redemptions!==null&&offer.remaining_redemptions!==undefined?`<span style="padding:5px 9px;border-radius:999px;background:#f4f7fa">${customerCampaignText('remaining')}: <b>${Number(offer.remaining_redemptions)}</b></span>`:''}
    </div>
    ${code?`<button type="button" data-customer-copy-coupon="${esc(code)}" class="btn primary" style="width:100%;margin-top:12px">${customerCampaignText('copy')} · ${esc(code)}</button>`:''}
  </article>`;
}
function customerNotificationCard(item){
  const unread=item.status==='unread';
  return `<article style="border:1px solid ${unread?'#ffd4bc':'#e5eaf0'};border-radius:16px;padding:13px;background:${unread?'#fff8f3':'#fff'}">
    <div style="display:flex;align-items:flex-start;gap:10px">
      <span style="width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:${unread?'#fff0e5':'#f3f6f9'};color:#ff651f">✦</span>
      <div style="flex:1;min-width:0">
        <div style="display:flex;justify-content:space-between;gap:10px">
          <strong style="font-size:13px;color:#14263c">${esc(item.title||'Notification')}</strong>
          ${unread?`<span style="font-size:9px;font-weight:800;color:#ff651f">${customerCampaignText('unread')}</span>`:''}
        </div>
        <p style="margin:5px 0 0;color:#5e6f82;font-size:11px;line-height:1.55">${esc(item.message||'')}</p>
        <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:8px">
          <small style="color:#8a98a8">${esc(customerCampaignDate(item.sent_at||item.created_at))}</small>
          ${unread?`<button type="button" class="customer-text-btn" data-customer-notification-read="${esc(item.id)}">${customerCampaignText('markRead')}</button>`:''}
        </div>
      </div>
    </div>
  </article>`;
}
function renderCustomerCampaignCenter(){
  if(!customerPortalRoot||customerPage!=='home')return;
  const recent=customerPortalRoot.querySelector('.customer-recent-section');
  if(!recent)return;
  const previous=document.querySelector('#customerCampaignCenter');
  if(previous)previous.remove();

  const unread=customerNotifications.filter(item=>item.status==='unread').length;
  const section=document.createElement('section');
  section.id='customerCampaignCenter';
  section.style.cssText='margin:18px 0 0;display:grid;gap:16px';
  section.innerHTML=`
    ${customerOffers.length?`<div>
      <div class="customer-section-heading customer-section-heading-inline" style="margin-bottom:10px">
        <div><small>GHAZALA OFFERS</small><h2>${customerCampaignText('offers')}</h2></div>
        <span style="min-width:28px;height:28px;padding:0 8px;border-radius:999px;display:grid;place-items:center;background:#fff0e5;color:#ff651f;font-size:11px;font-weight:900">${customerOffers.length}</span>
      </div>
      <div style="display:grid;gap:10px">${customerOffers.map(customerOfferCard).join('')}</div>
    </div>`:''}
    ${customerNotifications.length?`<div>
      <div class="customer-section-heading customer-section-heading-inline" style="margin-bottom:10px">
        <div><small>${customerCampaignText('latest')}</small><h2>${customerCampaignText('notifications')}</h2></div>
        <div style="display:flex;align-items:center;gap:8px">
          ${unread?`<span style="min-width:26px;height:26px;padding:0 7px;border-radius:999px;display:grid;place-items:center;background:#ff651f;color:#fff;font-size:10px;font-weight:900">${unread}</span>
          <button type="button" class="customer-text-btn" data-customer-notifications-read-all>${customerCampaignText('markAll')}</button>`:''}
        </div>
      </div>
      <div style="display:grid;gap:8px">${customerNotifications.slice(0,5).map(customerNotificationCard).join('')}</div>
    </div>`:''}
  `;
  if(section.innerHTML.trim()){
    recent.parentNode.insertBefore(section,recent);
  }else{
    return;
  }

  section.querySelectorAll('[data-customer-copy-coupon]').forEach(button=>{
    button.onclick=async()=>{
      const code=button.dataset.customerCopyCoupon||'';
      try{await navigator.clipboard.writeText(code)}catch(_){}
      toast(customerCampaignText('copied')+': '+code);
    };
  });
  section.querySelectorAll('[data-customer-notification-read]').forEach(button=>{
    button.onclick=async()=>{
      const id=button.dataset.customerNotificationRead;
      try{
        await api(`/api/customer/notifications/${encodeURIComponent(id)}/read`,{method:'POST',body:'{}'});
        await customerRefresh();
        renderCustomerPortal();
      }catch(error){toast(error.message||'Could not update notification.')}
    };
  });
  const readAll=section.querySelector('[data-customer-notifications-read-all]');
  if(readAll)readAll.onclick=async()=>{
    try{
      await api('/api/customer/notifications/read-all',{method:'POST',body:'{}'});
      await customerRefresh();
      renderCustomerPortal();
    }catch(error){toast(error.message||'Could not update notifications.')}
  };
}

