async function wireCustomerCreateShipment(){
  if(!customerProfile)return customerGo('login');
  const form=document.querySelector('#customerShipmentForm');
  const address=document.querySelector('#customerShipmentSenderAddress');
  const senderPhone=document.querySelector('#customerShipmentSenderPhone');
  const method=document.querySelector('#customerShipmentPaymentMethod');
  const codField=document.querySelector('#customerCodField');
  const quoteButton=document.querySelector('#customerCalculateQuoteBtn');
  const origin=document.querySelector('#customerShipmentOrigin');
  const destination=document.querySelector('#customerShipmentDestination');
  const destinationBranch=form?.elements?.namedItem('recipient_branch');

  if(!form)return;

  try{
    await Promise.all([loadGhazalaNetwork(),ensureCustomerPricing()]);
  }catch(error){
    // Pricing/network helpers are useful for previews, but must never disable
    // the actual customer shipment submit flow.
    console.warn('Customer shipment helper data unavailable:',error);
  }

  const previousOrigin=origin?.value||'';
  const previousDestination=destination?.value||'';
  populateCitySelect(origin,previousOrigin);
  populateCitySelect(destination,previousDestination);

  const refreshDestinationBranches=()=>{
    if(destinationBranch)populateBranchSelect(destinationBranch,destination?.value||'',destinationBranch.value||'');
  };
  refreshDestinationBranches();
  if(destination)destination.onchange=refreshDestinationBranches;

  if(address&&!address.value)address.value=customerProfile.address||'';
  if(senderPhone&&!senderPhone.value)senderPhone.value=customerProfile.mobile||'';

  const toggleCod=()=>{if(codField)codField.hidden=method?.value!=='cod'};
  toggleCod();
  if(method)method.onchange=toggleCod;

  const quoteRequiredFields=[
    ['origin','Pickup City'],
    ['destination','Delivery City'],
    ['sender_id','ID / Iqama Number'],
    ['sender_phone','Sender Mobile Number'],
    ['sender_address','Pickup Address'],
    ['recipient','Recipient Name'],
    ['phone','Recipient Mobile Number'],
    ['recipient_id','Recipient ID / Iqama Number'],
    ['recipient_address','Recipient Address'],
    ['pieces','Pieces'],
    ['payment_method','Payment Method'],
    ['eta','Expected Delivery Time']
  ];
  const resetQuoteDisplay=()=>{
    const target=document.querySelector('#customerQuoteTotal');
    const summary=document.querySelector('#customerPricingLiveSummary');
    if(target){
      delete target.dataset.amount;
      target.textContent='— '+customerTranslate('ر.س');
    }
    if(summary)summary.innerHTML='';
  };
  const firstMissingQuoteField=()=>quoteRequiredFields.find(([name])=>{
    const field=form.elements.namedItem(name);
    return !field || !String(field.value||'').trim();
  });
  const showQuote=async(showError=true)=>{
    const target=document.querySelector('#customerQuoteTotal');
    const summary=document.querySelector('#customerPricingLiveSummary');
    const missing=firstMissingQuoteField();
    if(missing){
      resetQuoteDisplay();
      if(showError){
        toast('Please complete: '+missing[1]);
        const field=form.elements.namedItem(missing[0]);
        try{
          field?.scrollIntoView({behavior:'smooth',block:'center'});
          setTimeout(()=>field?.focus(),250);
        }catch(_){}
      }
      return null;
    }
    const originValue=String(origin?.value||'').trim();
    const destinationValue=String(destination?.value||'').trim();
    if(!originValue||!destinationValue||originValue===destinationValue){
      resetQuoteDisplay();
      if(showError)toast(customerTranslate('مدينة الاستلام والتسليم يجب أن تكون مختلفة'));
      return null;
    }
    try{
      const quote=await customerServerQuote(form);
      const hidden=form.elements.namedItem('pricing_size_code');
      if(hidden&&quote.size_code)hidden.value=quote.size_code;
      customerPreferredPricingSizeCode=quote.size_code||hidden?.value||'';
      if(target){
        target.dataset.amount=quote.total_fee;
        target.textContent=Number(quote.total_fee||0).toFixed(2)+' '+customerTranslate('ر.س');
      }
      if(summary)summary.innerHTML=customerQuoteSummaryMarkup(quote);
      const grid=document.querySelector('#customerPricing3DGrid');
      if(grid){
        grid.innerHTML=customerPricingCardsMarkup(customerPreferredPricingSizeCode);
        bindCustomerPricingCards(grid,form,()=>showQuote());
      }
      return quote;
    }catch(error){
      resetQuoteDisplay();
      if(showError)toast(error.message);
      if(summary&&showError)summary.innerHTML=`<div class="notice-error">${esc(error.message)}</div>`;
      return null;
    }
  };
  reorderCustomerShipmentForm(form);
  if(quoteButton)quoteButton.onclick=()=>showQuote();

  resetQuoteDisplay();

  form.onsubmit=async e=>{
    e.preventDefault();

    const requiredFields=[
      ['origin','Pickup City'],
      ['destination','Delivery City'],
      ['sender_id','ID / Iqama Number'],
      ['sender_phone','Sender Mobile Number'],
      ['sender_address','Pickup Address'],
      ['recipient','Recipient Name'],
      ['phone','Recipient Mobile Number'],
      ['recipient_id','Recipient ID / Iqama Number'],
      ['recipient_address','Recipient Address'],
      ['pieces','Pieces'],
      ['payment_method','Payment Method'],
      ['eta','Expected Delivery Time']
    ];
    const missing=requiredFields.find(([name])=>{
      const field=form.elements.namedItem(name);
      return !field || !String(field.value||'').trim();
    });
    if(missing){
      const field=form.elements.namedItem(missing[0]);
      toast('Please complete: '+missing[1]);
      try{
        field?.scrollIntoView({behavior:'smooth',block:'center'});
        setTimeout(()=>field?.focus(),250);
      }catch(_){}
      return;
    }

    const originValue=String(origin?.value||'').trim();
    const destinationValue=String(destination?.value||'').trim();
    if(!originValue||!destinationValue)return toast(customerTranslate('اختر مدينة الاستلام ومدينة التسليم'));
    if(originValue===destinationValue)return toast(customerTranslate('مدينة الاستلام والتسليم يجب أن تكون مختلفة'));

    const payload=Object.fromEntries(new FormData(form));
    payload.notification_language=currentLang;
    payload.promo_code=String(payload.promo_code||'').trim().toUpperCase();
    payload.pricing_size_code=String(payload.pricing_size_code||'').trim().toUpperCase();
    payload.origin=originValue;
    payload.destination=destinationValue;
    if(destinationBranch)payload.recipient_branch=String(destinationBranch.value||'').trim().toUpperCase();
    ['pieces','weight','length_cm','width_cm','height_cm','declared_value','cod'].forEach(key=>payload[key]=Number(payload[key]||0));
    payload.insured=!!document.querySelector('#customerShipmentInsured')?.checked;

    const submit=form.querySelector('[type="submit"]');
    submit.disabled=true;
    try{
      const verifiedQuote=await showQuote(false);
      if(verifiedQuote){
        payload.pricing_size_code=String(form.elements.namedItem('pricing_size_code')?.value||verifiedQuote.size_code||payload.pricing_size_code||'').trim().toUpperCase();
      }
      const result=await api('/api/customer/shipments',{method:'POST',body:JSON.stringify(payload)});
      customerPreferredPricingSizeCode='';
      await customerRefresh();
      toast(customerTranslate('تم إنشاء الشحنة')+' '+result.awb);
      customerPage='shipments';
      renderCustomerPortal();
      await customerReceiptModal(result.awb);
    }catch(err){
      toast(err.message);
    }finally{
      if(submit?.isConnected)submit.disabled=false;
    }
  };
}

