function customerNotificationPrefText(key){
  const row=CUSTOMER_NOTIFICATION_PREF_TEXT[key]||{};
  return row[customerLang]||row.en||key;
}
function customerNotificationProviderBadge(provider){
  const ready=!!provider?.configured;
  const label=ready?customerNotificationPrefText('configured'):customerNotificationPrefText('notConfigured');
  return `<small style="display:inline-flex;align-items:center;gap:5px;margin-inline-start:auto;padding:3px 8px;border-radius:999px;background:${ready?'#ecfdf5':'#fff7ed'};color:${ready?'#047857':'#c2410c'}">${ready?'✓':'!'} ${esc(label)}</small>`;
}
async function customerNotificationPreferencesModal(){
  if(!user||accessRole()!=='customer')return customerGo('login');
  const root=document.querySelector('#modalRoot');
  root.innerHTML=`<div class="modal-backdrop" data-close><section class="modal" style="max-width:760px;max-height:92vh;overflow:auto"><div class="modal-head"><h2>${esc(customerNotificationPrefText('title'))}</h2><button class="icon-btn" type="button" data-close>×</button></div><p>${esc(customerNotificationPrefText('loading'))}</p></section></div>`;
  wireModal();
  try{
    const prefs=await api('/api/customer/notification-preferences');
    // Preferences must not depend on loading the full notification center.
    // Provider readiness is returned by the preferences endpoint itself.
    const providers=prefs?.providers||{};
    const channelRows=[['in_app_enabled','in_app'],['sms_enabled','sms'],['whatsapp_enabled','whatsapp'],['email_enabled','email']];
    const categoryRows=['shipment_updates','payment_updates','delivery_updates','pickup_updates','marketing_updates'];
    const languages=[['en','English'],['ar','العربية'],['ur','اردو'],['hi','हिन्दी'],['bn','বাংলা']];
    root.innerHTML=`<div class="modal-backdrop" data-close><section class="modal" style="max-width:760px;max-height:92vh;overflow:auto"><div class="modal-head"><div><small style="color:#ff651f;font-weight:800">GHAZALA NOTIFICATIONS</small><h2 style="margin:4px 0 0">${esc(customerNotificationPrefText('title'))}</h2><p style="margin:6px 0 0;color:#64748b">${esc(customerNotificationPrefText('subtitle'))}</p></div><button class="icon-btn" type="button" data-close>×</button></div>
      <form id="customerNotificationPrefsForm" class="form-grid">
        <div class="field span-2"><span style="font-weight:800;display:block;margin-bottom:8px">${esc(customerNotificationPrefText('channels'))}</span><div style="display:grid;gap:8px">${channelRows.map(([field,key])=>`<label class="card" style="padding:11px;box-shadow:none;display:flex;gap:10px;align-items:center"><input type="checkbox" name="${field}" ${prefs?.[field]?'checked':''}><b>${esc(customerNotificationPrefText(key))}</b>${customerNotificationProviderBadge(providers?.[key])}</label>`).join('')}</div></div>
        <div class="field span-2"><small style="color:#64748b;display:block;line-height:1.5">${esc(customerNotificationPrefText('providerNote'))}</small></div>
        <div class="field span-2"><span style="font-weight:800;display:block;margin-bottom:8px">${esc(customerNotificationPrefText('categories'))}</span><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px">${categoryRows.map(field=>`<label class="card" style="padding:11px;box-shadow:none;display:flex;gap:10px;align-items:center"><input type="checkbox" name="${field}" ${prefs?.[field]?'checked':''}><span>${esc(customerNotificationPrefText(field))}</span></label>`).join('')}</div></div>
        <label class="field span-2"><span>${esc(customerNotificationPrefText('language'))}</span><select name="preferred_language">${languages.map(([code,label])=>`<option value="${code}" ${String(prefs?.preferred_language||'en')===code?'selected':''}>${label}</option>`).join('')}</select></label>
        <div class="field span-2"><button class="btn primary full" type="submit">${esc(customerNotificationPrefText('save'))}</button></div>
      </form></section></div>`;
    wireModal();
    const form=document.querySelector('#customerNotificationPrefsForm');
    form.onsubmit=async event=>{
      event.preventDefault();
      const button=form.querySelector('[type="submit"]');
      button.disabled=true;
      const payload={preferred_language:String(form.elements.preferred_language.value||'en')};
      for(const [field] of channelRows)payload[field]=!!form.elements[field].checked;
      for(const field of categoryRows)payload[field]=!!form.elements[field].checked;
      try{
        await api('/api/customer/notification-preferences',{method:'PATCH',body:JSON.stringify(payload)});
        toast(customerNotificationPrefText('saved'));
        closeModal();
      }catch(err){toast(customerTranslate(err.message||customerNotificationPrefText('error')))}
      finally{if(button?.isConnected)button.disabled=false}
    };
  }catch(err){
    root.innerHTML=`<div class="modal-backdrop" data-close><section class="modal" style="max-width:620px"><div class="modal-head"><h2>${esc(customerNotificationPrefText('title'))}</h2><button class="icon-btn" type="button" data-close>×</button></div><div class="card empty">${esc(customerNotificationPrefText('error'))}<br><small>${esc(err.message||'')}</small></div></section></div>`;
    wireModal();
  }
}


function customerCurrency(amount,currency='SAR'){
  const code=String(currency||'SAR').trim().toUpperCase();
  const label=code==='SAR'?customerTranslate('ر.س'):code;
  return `${Number(amount||0).toLocaleString(customerLang==='ar'?'ar-SA':customerLang==='ur'?'ur-PK':'en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})} ${label}`;
}

