async function customerDownloadFile(url,fallback='document.pdf'){
  const response=await fetch(url,{credentials:'same-origin',headers:{Accept:'application/pdf'}});
  if(!response.ok){
    let message=customerTranslate('تعذر تنزيل الملف');
    try{message=(await response.json()).error||message}catch(_){}
    throw new Error(message);
  }
  const blob=await response.blob();
  const href=URL.createObjectURL(blob);
  const disposition=response.headers.get('Content-Disposition')||'';
  const match=disposition.match(/filename="?([^";]+)"?/i);
  const link=document.createElement('a');
  link.href=href;
  link.download=(match?.[1]||fallback).replace(/[\\/\r\n]/g,'_');
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(()=>URL.revokeObjectURL(href),30000);
}

