async function customerTrackShipment(awb){
  const normalized=String(awb||'').trim().toUpperCase();
  if(!normalized)return toast('أدخل رقم الشحنة');
  try{
    customerTrackingResult=await api('/api/public/tracking/'+encodeURIComponent(normalized));
    customerPage='tracking';
    renderCustomerPortal();
  }catch(err){
    toast(err.message);
  }
}

function customerTrackingEventText(value){
  const raw=String(value??'').trim();
  if(!raw)return '';

  const localizedReason=(reason)=>{
    const reasons={
      'لا يوجد رد':{
        ar:'لا يوجد رد',en:'No answer',ur:'جواب نہیں ملا',hi:'कोई जवाब नहीं',bn:'কোনো উত্তর নেই'
      },
      'المستلم غير متاح':{
        ar:'المستلم غير متاح',en:'Recipient unavailable',ur:'وصول کنندہ دستیاب نہیں',hi:'प्राप्तकर्ता उपलब्ध नहीं',bn:'প্রাপক উপলব্ধ নয়'
      },
      'العنوان غير صحيح أو غير مكتمل':{
        ar:'العنوان غير صحيح أو غير مكتمل',en:'Wrong or incomplete address',ur:'غلط یا نامکمل پتہ',hi:'गलत या अधूरा पता',bn:'ভুল বা অসম্পূর্ণ ঠিকানা'
      },
      'رفض المستلم الشحنة':{
        ar:'رفض المستلم الشحنة',en:'Recipient refused shipment',ur:'وصول کنندہ نے شپمنٹ لینے سے انکار کیا',hi:'प्राप्तकर्ता ने शिपमेंट लेने से मना किया',bn:'প্রাপক শিপমেন্ট নিতে অস্বীকার করেছেন'
      },
      'مشكلة في الدفع أو التحصيل':{
        ar:'مشكلة في الدفع أو التحصيل',en:'Payment or COD issue',ur:'ادائیگی یا COD کا مسئلہ',hi:'भुगतान या COD समस्या',bn:'পেমেন্ট বা COD সমস্যা'
      },
      'تعذر الوصول إلى موقع التسليم':{
        ar:'تعذر الوصول إلى موقع التسليم',en:'Could not access delivery location',ur:'ڈیلیوری مقام تک رسائی نہیں ہو سکی',hi:'डिलीवरी स्थान तक पहुंच नहीं हो सकी',bn:'ডেলিভারি স্থানে পৌঁছানো যায়নি'
      },
      'مشكلة في حالة الطرد':{
        ar:'مشكلة في حالة الطرد',en:'Parcel condition issue',ur:'پارسل کی حالت کا مسئلہ',hi:'पार्सल की स्थिति में समस्या',bn:'পার্সেলের অবস্থায় সমস্যা'
      },
      'سبب آخر':{
        ar:'سبب آخر',en:'Other',ur:'دیگر وجہ',hi:'अन्य कारण',bn:'অন্যান্য কারণ'
      }
    };
    const row=reasons[reason];
    return row?.[customerLang]||row?.en||customerTranslate(reason);
  };

  let match=raw.match(/^محاولة تسليم رقم\s*(\d+)$/);
  if(match){
    const n=match[1];
    const labels={
      ar:`محاولة تسليم رقم ${n}`,
      en:`Delivery Attempt #${n}`,
      ur:`ڈیلیوری کوشش #${n}`,
      hi:`डिलीवरी प्रयास #${n}`,
      bn:`ডেলিভারি প্রচেষ্টা #${n}`
    };
    return labels[customerLang]||labels.en;
  }

  match=raw.match(/^محاولة تسليم فاشلة\s*·\s*(.+)$/);
  if(match){
    const reason=localizedReason(match[1].trim());
    const labels={
      ar:`محاولة تسليم فاشلة · ${reason}`,
      en:`Failed Delivery Attempt · ${reason}`,
      ur:`ناکام ڈیلیوری کوشش · ${reason}`,
      hi:`असफल डिलीवरी प्रयास · ${reason}`,
      bn:`ব্যর্থ ডেলিভারি প্রচেষ্টা · ${reason}`
    };
    return labels[customerLang]||labels.en;
  }

  return customerTranslate(raw);
}

function customerTrackingDate(value){
  if(!value)return '—';
  const raw=String(value).trim();
  const normalized=/[zZ]|[+-]\d{2}:?\d{2}$/.test(raw)?raw:raw.replace(' ','T');
  const date=new Date(normalized);
  if(Number.isNaN(date.getTime()))return raw;
  const locales={ar:'ar-SA',en:'en-GB',ur:'ur-PK',hi:'hi-IN',bn:'bn-BD'};
  try{
    return date.toLocaleString(locales[customerLang]||'en-GB',{
      day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'
    });
  }catch(_){
    return raw;
  }
}

function customerTrackingLabel(key){
  const labels={
    nextAttempt:{
      ar:'موعد محاولة التسليم القادمة',
      en:'Next Delivery Attempt',
      ur:'اگلی ڈیلیوری کوشش',
      hi:'अगला डिलीवरी प्रयास',
      bn:'পরবর্তী ডেলিভারি প্রচেষ্টা'
    },
    exceptionTitle:{
      ar:'تعذر التسليم',en:'Delivery Exception',ur:'ڈیلیوری میں رکاوٹ',hi:'डिलीवरी अपवाद',bn:'ডেলিভারি ব্যতিক্রম'
    },
    attemptNumber:{
      ar:'رقم المحاولة',en:'Attempt',ur:'کوشش',hi:'प्रयास',bn:'প্রচেষ্টা'
    },
    failureReason:{
      ar:'سبب تعذر التسليم',en:'Reason',ur:'وجہ',hi:'कारण',bn:'কারণ'
    },
    failureDetails:{
      ar:'تفاصيل السبب',en:'Reason Details',ur:'وجہ کی تفصیل',hi:'कारण का विवरण',bn:'কারণের বিস্তারিত'
    }
  };
  return labels[key]?.[customerLang]||labels[key]?.en||key;
}

function customerFailureReasonFromCode(code){
  const reasons={
    no_answer:{ar:'لا يوجد رد',en:'No answer',ur:'جواب نہیں ملا',hi:'कोई जवाब नहीं',bn:'কোনো উত্তর নেই'},
    recipient_unavailable:{ar:'المستلم غير متاح',en:'Recipient unavailable',ur:'وصول کنندہ دستیاب نہیں',hi:'प्राप्तकर्ता उपलब्ध नहीं',bn:'প্রাপক উপলব্ধ নয়'},
    wrong_address:{ar:'العنوان غير صحيح أو غير مكتمل',en:'Wrong or incomplete address',ur:'غلط یا نامکمل پتہ',hi:'गलत या अधूरा पता',bn:'ভুল বা অসম্পূর্ণ ঠিকানা'},
    refused:{ar:'رفض المستلم الشحنة',en:'Recipient refused shipment',ur:'وصول کنندہ نے شپمنٹ لینے سے انکار کیا',hi:'प्राप्तकर्ता ने शिपमेंट लेने से मना किया',bn:'প্রাপক শিপমেন্ট নিতে অস্বীকার করেছেন'},
    payment_issue:{ar:'مشكلة في الدفع أو التحصيل',en:'Payment or COD issue',ur:'ادائیگی یا COD کا مسئلہ',hi:'भुगतान या COD समस्या',bn:'পেমেন্ট বা COD সমস্যা'},
    access_issue:{ar:'تعذر الوصول إلى موقع التسليم',en:'Could not access delivery location',ur:'ڈیلیوری مقام تک رسائی نہیں ہو سکی',hi:'डिलीवरी स्थान तक पहुंच नहीं हो सकी',bn:'ডেলিভারি স্থানে পৌঁছানো যায়নি'},
    damaged:{ar:'مشكلة في حالة الطرد',en:'Parcel condition issue',ur:'پارسل کی حالت کا مسئلہ',hi:'पार्सल की स्थिति में समस्या',bn:'পার্সেলের অবস্থায় সমস্যা'},
    other:{ar:'سبب آخر',en:'Other',ur:'دیگر وجہ',hi:'अन्य कारण',bn:'অন্যান্য কারণ'}
  };
  const row=reasons[String(code||'').trim()];
  return row?.[customerLang]||row?.en||'';
}

function wireCustomerTrackingResult(){
  const root=document.querySelector('#customerTrackingResult');
  if(!root)return;
  if(!customerTrackingResult){
    root.innerHTML=`<div class="customer-mini-empty"><span>⌕</span><div><strong>${esc(customerTranslate('أدخل رقم شحنة للتتبع'))}</strong></div></div>`;
    return;
  }

  const s=customerTrackingResult;
  const events=Array.isArray(s.events)?s.events:[];
  const delivered=isDeliveredRecord(s);
  const failedReason=customerFailureReasonFromCode(s.failure_reason_code)||'';
  const exceptionCard=(!delivered&&(s.next_attempt_at||s.failure_reason_code||s.failure_reason_text))?`
    <div class="customer-tracking-summary-card" style="border-color:rgba(234,88,12,.28);background:rgba(255,247,237,.72)">
      <h3 style="margin:0 0 10px">${esc(customerTrackingLabel('exceptionTitle'))}</h3>
      <div class="customer-tracking-meta">
        ${s.failed_attempt_number?`<div><small>${esc(customerTrackingLabel('attemptNumber'))}</small><strong>#${esc(s.failed_attempt_number)}</strong></div>`:''}
        ${failedReason?`<div><small>${esc(customerTrackingLabel('failureReason'))}</small><strong>${esc(failedReason)}</strong></div>`:''}
        ${s.failure_reason_text?`<div><small>${esc(customerTrackingLabel('failureDetails'))}</small><strong>${esc(s.failure_reason_text)}</strong></div>`:''}
        ${s.next_attempt_at?`<div><small>${esc(customerTrackingLabel('nextAttempt'))}</small><strong>${esc(customerTrackingDate(s.next_attempt_at))}</strong></div>`:''}
      </div>
    </div>`:'';
  root.innerHTML=`
    <div class="customer-tracking-summary-card">
      <h2>${esc(s.awb||'')}</h2>
      <p>${esc(customerTranslate(s.status||''))} · ${esc(customerTrackingEventText(s.stage||''))}</p>
      <div class="customer-tracking-meta">
        <div><small>${esc(customerTranslate('من'))}</small><strong>${esc(customerTranslate(s.origin||'—'))}</strong></div>
        <div><small>${esc(customerTranslate('إلى'))}</small><strong>${esc(customerTranslate(s.destination||'—'))}</strong></div>
        <div><small>${esc(customerTranslate('الموقع الحالي'))}</small><strong>${esc(customerTranslate(s.current_location||'—'))}</strong></div>
        ${isDeliveredRecord(s)?'':`${s.next_attempt_at?'':`<div><small>${esc(customerTranslate('ETA'))}</small><strong>${esc(s.eta||'—')}</strong></div>`}${s.next_attempt_at?`<div><small>${esc(customerTrackingLabel('nextAttempt'))}</small><strong>${esc(customerTrackingDate(s.next_attempt_at))}</strong></div>`:''}`}
      </div>
    </div>
    ${exceptionCard}
    <div class="customer-tracking-timeline">
      ${events.length?events.slice().reverse().map(ev=>`
        <div class="customer-track-event">
          <span>✓</span>
          <div><strong>${esc(customerTrackingEventText(ev.stage||ev.status||''))}</strong><small>${esc(customerTranslate(ev.location||''))} · ${esc(customerTrackingDate(ev.created_at||''))}</small></div>
        </div>`).join(''):`<div class="customer-track-event"><span>•</span><div><strong>${esc(customerTranslate(s.status||''))}</strong><small>${esc(customerTranslate(s.current_location||s.origin||''))}</small></div></div>`}
    </div>`;
}


